    example: 123,
    description: 'Order ID',
  })
  @IsNumber()
  orderId!: number;

  @ApiProperty({
    example: 299.99,
    description: 'Amount collected',
  })
  @IsNumber()
  @Min(0.01)
  amountCollected!: number;

  @ApiProperty({
    example: 'USD',
    description: 'Currency code',
  })
  @IsString()
  currency!: string;

  @ApiPropertyOptional({
    example: 'driver-456',
    description: 'Delivery driver ID',
  })
  @IsOptional()
  @IsString()
  collectedBy?: string;

  @ApiPropertyOptional({
    example: 'Collected at user doorstep',
    description: 'Collection notes',
  })
  @IsOptional()
  @IsString()
  notes?: string;
}

